  Object.assign(state,{nwRange:'12个月',nwLine:'net',nwStatus:['data','empty','loading','error'].includes(new URLSearchParams(location.search).get('nwState'))?new URLSearchParams(location.search).get('nwState'):'data'});
  const nwLines=[['net','净资产'],['assets','总资产'],['liabilities','总负债']];
  function nwValues(line=state.nwLine,range=state.nwRange){const a=[28700,28600,29700,30000,29500,31000,31500,31200,32000,32800,32400,32750.82],d=[-2100,-2200,-2000,-2400,-2300,-2200,-2000,-2100,-2200,-2000,-1900,-1860.82];let v=line==='assets'?a:line==='liabilities'?d:a.map((x,i)=>x+d[i]);const n={'3个月':3,'6个月':6,'12个月':12,'全部':12}[range];return v.slice(-n);}
  function nwMoney(v,signed=false){return state.hide?'••••':`¥${signed&&v>=0?'+':''}${v.toLocaleString('en-US',{maximumFractionDigits:2})}`;}
  function nwPlot(v){const min=Math.min(...v),max=Math.max(...v),span=max-min||1,point=(x,i)=>[12+i*296/Math.max(v.length-1,1),12+(1-(x-min)/span)*208],p=v.map(point);return `<svg class="nw-chart" viewBox="0 0 320 240" role="img" aria-label="${nwLines.find(x=>x[0]===state.nwLine)[1]}趋势${state.hide?'，金额已隐藏':''}"><g stroke="var(--bc-line)" stroke-width="1">${[48,96,144,192].map(y=>`<path d="M8 ${y}H312"/>`).join('')}</g><polyline points="${p.map(x=>x.join(',')).join(' ')}" fill="none" stroke="var(--bc-accent)" stroke-width="2"/>${p.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="2.5" fill="var(--bc-accent)"/><text x="${x}" y="${y-12}" text-anchor="middle" fill="var(--bc-text)" font-size="9">${state.hide?'**':Math.abs(v[i])>=10000?(v[i]/10000).toFixed(1)+'w':Math.round(v[i])}</text>`).join('')}<g font-size="10" fill="var(--bc-muted)"><text x="8" y="237">${state.nwRange==='3个月'?'26/8':state.nwRange==='6个月'?'26/5':'25/11'}</text><text x="290" y="237">26/10</text></g></svg>`;}
  function nwBody(){const v=nwValues(),first=v[0],last=v.at(-1),delta=last-first;return `<div class="nw-page"><div class="nw-ranges">${['3个月','6个月','12个月','全部'].map(x=>btn('nw-range:'+x,x,x,'p-chip',`aria-pressed="${state.nwRange===x}"`)).join('')}</div>${state.nwStatus==='loading'?surface('<div class="nw-skeleton" role="status">正在读取趋势…</div>'):state.nwStatus==='error'?surface(`<div class="bc-between">读取失败${btn('nw-retry','重试','重试','bc-secondary')}</div>`):`${state.nwStatus==='data'?surface(`<div class="nw-identity"><span>${icon('chart-no-axes-combined')}</span><div><h3>${nwLines.find(x=>x[0]===state.nwLine)[1]}</h3><small>CNY · ${state.nwRange}</small></div></div><p class="bc-small">期末金额</p><strong class="nw-amount bc-num">${nwMoney(last)}</strong><div class="nw-metrics"><div><small>期初金额</small><b>${nwMoney(first)}</b></div><div><small>期间变化</small><b>${nwMoney(delta,true)}</b></div>${!state.hide&&first!==0?`<div><small>变化比例</small><b>${delta>=0?'+':''}${(delta/Math.abs(first)*100).toFixed(1)}%</b></div>`:''}</div>`):''}${surface(`<h3>净值趋势</h3><div class="nw-lines">${nwLines.map(([key,label])=>btn('nw-line:'+key,label,label,'',`aria-pressed="${state.nwLine===key}"`)).join('')}</div>${state.nwStatus==='empty'?'<div class="nw-empty">暂无数据</div>':nwPlot(v)}`)}<p class="bc-small nw-note">按当前汇率折算为主币种；缺少汇率的账户暂不计入。</p>`}</div>`;}
  fDefs.networth.title='净值趋势';fDefs.networth.body=nwBody;
  const nwPreviousRender=fRender;fRender=function(key){if(key!=='networth')return nwPreviousRender(key);return `<div class="bc-subhead"><div class="bc-heading-left">${btn('back',icon('chevron-left'),'返回')}<h2>净值趋势</h2></div>${btn('nw-privacy',icon(state.hide?'eye-off':'eye'),state.hide?'显示金额':'隐藏金额','bc-icon')}</div><div class="nw-scroll">${nwBody()}</div>`;};
  root.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el?.dataset.action.startsWith('nw-'))return;event.preventDefault();event.stopImmediatePropagation();const [kind,value]=el.dataset.action.split(':');if(kind==='nw-range')state.nwRange=value;else if(kind==='nw-line')state.nwLine=value;else if(kind==='nw-privacy')state.hide=!state.hide;else if(kind==='nw-retry')state.nwStatus='data';render();persist();},true);
  const nwPreviousAfter=qAfterRender;qAfterRender=function(){nwPreviousAfter();for(const value of phone.querySelectorAll('.nw-metrics b')){value.style.fontSize='';const size=parseFloat(getComputedStyle(value).fontSize);if(value.scrollWidth>value.clientWidth)value.style.fontSize=(size*value.clientWidth/value.scrollWidth)+'px';}};
